bounded_host_request.command:
set -euo pipefail
root="$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
owner="$(cat "$root/deploy/secrets/bug_report_userbot_account.txt")"
[[ "$owner" =~ ^[1-9][0-9]{3,18}$ ]] || exit 61
count="$(docker exec deploy-postgres-1 psql -X -v ON_ERROR_STOP=1 -U gace -d gaybbs -Atc "SELECT jsonb_array_length(data->'buttons') FROM public_post_drafts WHERE owner_user_id=$owner AND module='link' AND step='preview' AND NOT data ? 'shareCode';" 2>/dev/null)" || exit 62
case "$count" in
 1) exit 81;;
 2) exit 82;;
 3) exit 83;;
 *) exit 84;;
esac
